<?php $title='Absensi';$page='attendance';$pdo=Database::connection();$uid=current_user()['id'];$q=$pdo->prepare('SELECT DISTINCT c.id,c.name FROM teacher_assignments a JOIN classes c ON c.id=a.class_id WHERE a.teacher_id=? ORDER BY c.name');$q->execute([$uid]);$classes=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Absensi Siswa</h1><p>Catat kehadiran harian siswa pada kelas yang diampu.</p></div></div><section class="panel"><form id="attendanceForm" class="form-grid four"><?= csrf_field() ?><label>Kelas<select name="class_id" id="attendanceClass"><?php foreach($classes as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Tanggal<input type="date" name="attendance_date" value="<?= date('Y-m-d') ?>"></label><label>Siswa ID<input type="number" name="student_id" placeholder="ID siswa" required></label><label>Status<select name="status"><option>Hadir</option><option>Izin</option><option>Sakit</option><option>Alpa</option></select></label><button class="btn btn-primary">Simpan Absensi</button></form><p class="muted">Catatan: gunakan ID siswa dari daftar pengguna. Pengembangan pemilih siswa berdasarkan kelas dapat ditambahkan pada tahap berikutnya.</p></section><?php require __DIR__.'/../_dashboard_end.php'; ?>